#Requires -Version 7
# Builds BinauralCore (native/binaural: the HRTF renderer used by the DCS audio module) and runs its tests: the
# interface contract (binaural_contract), the offline harness A1-A13 (binaural_core) and A14 on the bundled generic set
# (binaural_default_data; it reports SKIP until native/binaural/data/sadie2_ku100.dcshrtf is generated by
# scripts/fetch-hrtf.ps1). Builds and tests run at BelowNormal priority.
# -DumpDir: WAV/CSV listening dumps of the harness (sweeps, ITD curve); not kept in the repository.
param([string]$DumpDir)
$ErrorActionPreference = 'Stop'
$workspaceRoot = Split-Path -Parent $PSScriptRoot
. (Join-Path $PSScriptRoot 'build-jobs.ps1')  # Get-BuildJobs: the compile jobs at once
$wrapper = Join-Path $PSScriptRoot 'msvc.cmd'
try { (Get-Process -Id $PID).PriorityClass = 'BelowNormal' } catch { }
$build = Join-Path $workspaceRoot 'artifacts/native/binaural'
& $wrapper cmake -S (Join-Path $workspaceRoot 'native/binaural') -B $build -G Ninja -DCMAKE_BUILD_TYPE=Release
if ($LASTEXITCODE -ne 0) { throw 'BinauralCore configuration failed.' }
& $wrapper cmake --build $build --parallel (Get-BuildJobs)
if ($LASTEXITCODE -ne 0) { throw 'BinauralCore build failed.' }
. (Join-Path $PSScriptRoot 'test-cache.ps1')
$testSources = @((Join-Path $workspaceRoot 'native/binaural'))  # its data and the C# fixture included
$testFingerprint = Get-NativeTestFingerprint $build $testSources
if ($DumpDir -or -not (Test-NativeTestsCurrent $build $testFingerprint)) {
    if ($DumpDir) { $env:BINAURAL_DUMP_DIR = $DumpDir }
    try {
        & $wrapper ctest --test-dir $build --output-on-failure -V
        if ($LASTEXITCODE -ne 0) { throw 'BinauralCore tests failed.' }
    } finally { if ($DumpDir) { Remove-Item Env:BINAURAL_DUMP_DIR } }
    Save-NativeTestsPassed $build $testFingerprint
}
